//! Std-only smoke run of the `rtps_secured_prefix` libFuzzer target
//! (`fuzz/fuzz_targets/`): the same harness
//! (`fuzz/harness/rtps_secured_prefix.rs`, included by path) driven by the
//! deterministic mutator in `fuzz/harness/smoke.rs` over the committed seed
//! corpus. See `fuzz/README.md`. The seeds are (re)generated by
//! `regenerate_seeds` (run with `--ignored`).

#[path = "../../../fuzz/harness/rtps_secured_prefix.rs"]
mod rtps_secured_prefix;
#[path = "../../../fuzz/harness/smoke.rs"]
mod smoke;

const DIR: &str = env!("CARGO_MANIFEST_DIR");

/// The Humble SROS 2 controller's prefix head
/// (`fixtures/captures/ros2-humble/sros2/lab/base_controller/cert.pem`).
const CONTROLLER: [u8; 12] = [0xaf, 0x0c, 0x85, 0x4b, 0x64, 0x6f, 0, 0, 0, 0, 0, 0];

fn seed(prefix: [u8; 12], subject: &str) -> Vec<u8> {
    let mut v = prefix.to_vec();
    v.extend_from_slice(subject.as_bytes());
    v
}

fn seeds() -> Vec<(&'static str, Vec<u8>)> {
    vec![
        (
            "seed-oneline.bin",
            seed(CONTROLLER, r"/CN=\/lab\/base_controller"),
        ),
        (
            "seed-rfc4514.bin",
            seed(CONTROLLER, "CN=/lab/base_controller"),
        ),
        (
            "seed-oid.bin",
            seed(CONTROLLER, "oid.2.5.4.3=/lab/base_controller"),
        ),
        (
            "seed-hex.bin",
            seed(
                CONTROLLER,
                "CN=#0c142f6c61622f626173655f636f6e74726f6c6c6572",
            ),
        ),
        (
            "seed-multi.bin",
            seed(
                [0x80; 12],
                r"C=US,O=Acme Robots+OU=R\2cD,CN=robot-1\ ,emailAddress=a@b.c",
            ),
        ),
        (
            "seed-escapes.bin",
            seed([0x81; 12], r"/CN=a\x2fb/DC=x/serialNumber=12"),
        ),
    ]
}

#[test]
#[ignore = "regenerates fuzz/corpus/rtps_secured_prefix"]
fn regenerate_seeds() {
    let dir = smoke::corpus_dir(DIR, "rtps_secured_prefix");
    std::fs::create_dir_all(&dir).unwrap();
    for (name, bytes) in seeds() {
        std::fs::write(dir.join(name), bytes).unwrap();
    }
}

#[test]
fn committed_seeds_match_the_generator() {
    let committed = smoke::corpus(DIR, "rtps_secured_prefix");
    for (_, s) in seeds() {
        assert!(
            committed.contains(&s),
            "a seed changed: run regenerate_seeds"
        );
    }
}

/// The harness's strongest invariant (a match survives no hash-bit flip)
/// needs matching inputs: the real subject in four spellings.
#[test]
fn the_real_subject_matches_through_the_harness() {
    for (_, s) in seeds().into_iter().take(4) {
        let subject = std::str::from_utf8(&s[12..]).unwrap();
        assert!(robodr_rtps::secured_prefix::prefix_matches_subject(
            &CONTROLLER,
            subject
        ));
        rtps_secured_prefix::run(&s);
    }
}

#[test]
fn rtps_secured_prefix_smoke() {
    let mut seeds: Vec<Vec<u8>> = smoke::corpus(DIR, "rtps_secured_prefix");
    seeds.extend(self::seeds().into_iter().map(|(_, s)| s));
    smoke::run(
        "rtps_secured_prefix",
        &seeds,
        0x5ec0_9e1f,
        &rtps_secured_prefix::run,
    );
}
